    "explanation": "Doğru cevap A’dır. CFTR proteini epitel hücrelerinde klor ve bikarbonat taşınmasında görev alır. Solunum yollarında CFTR fonksiyon bozukluğu klor sekresyonunu azaltır ve ENaC aracılı sodyum geri emilimini artırarak suyun lümenden çekilmesine neden olur. Sonuçta hava yolu yüzey sıvısı azalır, mukus dehidrate ve viskoz hâle gelir. Bu durum mukosiliyer klirensi bozar, tekrarlayan enfeksiyonlara ve bronşektazi gelişimine zemin hazırlar. Diğer seçenekler alfa-1 antitripsin eksikliği, surfaktan veya oksijen taşıma fizyolojisiyle ilgilidir. Kistik fibrozis CFTR klor kanalındaki bozukluk nedeniyle epitel iyon ve su taşınmasını etkiler. Hava yollarında klor sekresyonu bozulur, sodyum ve su geri emilimi artar; epitel yüzey sıvısı azalır ve koyu, yapışkan sekresyonlar oluşur. TUS açısından ayırıcı nokta: Kistik fibrozis = CFTR bozukluğu + dehidrate mukus + bozulmuş mukosiliyer klirens + tekrarlayan akciğer enfeksiyonları.",
