    "coreKnowledge": "Para-aminohippurat düşük plazma konsantrasyonlarında glomerüler filtrasyon ve güçlü proksimal tübüler sekresyon ile neredeyse tamamen plazmadan temizlenir. Bu nedenle PAH klirensi etkin renal plazma akımının tahmininde kullanılır.",
    "explanation": "Doğru cevap B’dir. PAH böbreğe gelen plazmadan glomerüler filtrasyon ve proksimal tübüler sekresyonla büyük oranda uzaklaştırılır. Tek geçişte tamamen değil ama çok yüksek oranda ekstrakte edildiği için klirensi etkin renal plazma akımını yaklaşık olarak yansıtır. İnülin ise filtre edilir; geri emilmez, sekrete edilmez ve metabolize edilmez, bu nedenle GFR ölçümünde altın standart kabul edilir. Kreatinin GFR tahmininde pratik kullanılır ancak hafif sekresyona uğrar. Üre geri emilir, sodyum ise yoğun regülasyona tabidir; bu nedenle renal plazma akımı tahmininde bu vaka için doğru klinik hedef değildir. Para-aminohippurat düşük plazma konsantrasyonlarında glomerüler filtrasyon ve güçlü proksimal tübüler sekresyon ile neredeyse tamamen plazmadan temizlenir. Bu nedenle PAH klirensi etkin renal plazma akımının tahmininde kullanılır. TUS açısından ayırıcı nokta: İnülin = GFR; PAH = etkin renal plazma akımı. Kreatinin pratik GFR tahminidir ama ideal değildir.",
    "answerAnalysisIntro": "Bu soru klirens maddelerini hangi renal parametreyi ölçtüklerine göre ayırmayı hedefler. İnülin GFR, PAH renal plazma akımı için düşünülmelidir.",
