      "Para-aminohippurat": "Doğrudur. PAH filtrasyon ve sekresyonla neredeyse tamamen temizlendiği için etkin renal plazma akımını tahmin eder. Bu nedenle renal hemodinamik hesaplamalarda klasik maddedir.",
      "Kreatinin": "Yanlıştır. Kreatinin GFR tahmininde kullanılır ancak tübüler sekresyon nedeniyle gerçek GFR’yi hafif fazla gösterebilir. Renal plazma akımı ölçümünün klasik maddesi değildir.",
