    "explanation": "Doğru cevap A’dır. Papiller tiroid karsinomu tiroidin diferansiye maligniteleri içinde en sık görülenidir ve genellikle iyi prognozludur. Foliküler epitelden köken alır; ancak yayılım paterni foliküler karsinomdan farklı olarak lenfatik yoldan servikal lenf nodlarına olma eğilimindedir. Histolojide optik olarak berrak nükleuslar, nükleer oluklar, intranükleer psödoinklüzyonlar ve psammom cisimcikleri klasik olarak vurgulanır. Kalsitonin medüller tiroid karsinomunda, erken hematojen yayılım ise foliküler karsinomda daha ön plandadır. Papiller tiroid karsinomu en sık tiroid malignitesidir. Foliküler epitel kökenlidir, lenfatik yayılım ve servikal lenf nodu tutulumu eğilimi gösterir; nükleer özellikler ve psammom cisimcikleri klasik patolojik ipuçlarıdır. TUS açısından ayırıcı nokta: Papiller tiroid karsinomu = en sık + lenfatik yayılım + psammom cisimcikleri + nükleer clearing/groove. Medüller = kalsitonin; foliküler = hematojen yayılım.",
