    "explanation": "Doğru cevap A’dır. Maple syrup urine disease, dallı zincirli aminoasitlerin yıkımındaki temel oksidatif dekarboksilasyon basamağının bozulmasıyla gelişir. Lösin, izolösin ve valin ile bunların alfa-ketoasitleri birikir; özellikle lösin nörotoksisite açısından önemlidir. Bu hastalık fenilketonüri, homosistinüri veya üre döngüsü defektlerinden farklı bir metabolik ekseni temsil eder. Sınavda “maple syrup kokusu”, neonatal beslenme bozulması, kusma, letarji ve nörolojik kötüleşme gibi ipuçları verilebilir; ancak temel biyokimyasal cevap dallı zincirli aminoasit katabolizmasıdır. Akçaağaç şurubu idrar hastalığı, lösin, izolösin ve valin gibi dallı zincirli aminoasitlerin katabolizmasında görevli dallı zincirli alfa-ketoasit dehidrogenaz kompleksi eksikliğiyle oluşur. TUS açısından ayırıcı nokta: MSUD = lösin, izolösin, valin birikimi + branched-chain alpha-ketoacid dehydrogenase eksikliği.",
