      "Gecikmiş rektifiye K+ kanallarından hücre dışına K+ çıkışı": "Yanlıştır. K+ çıkışı repolarizasyon fazlarında önemlidir. Faz 0 hızlı depolarizasyonu açıklamaz.",
      "If akımı ile yavaş diyastolik depolarizasyon": "Yanlıştır. If akımı pacemaker hücrelerinde faz 4 yavaş diyastolik depolarizasyonla ilişkilidir. Ventrikül miyosit faz 0’ı için temel mekanizma değildir.",
