      "SNARE proteinlerini parçalayarak asetilkolin salınımını engellemesi": "Yanlıştır. SNARE proteinlerinin parçalanması botulinum ve tetanoz toksinleriyle ilişkilidir. Pertussis toksini nörotransmitter salınımını bu mekanizmayla engellemez.",
