      "Gi proteinini ADP-ribozilleyerek adenilat siklaz inhibisyonunu engellemesi ve cAMP artışı oluşturması": "Doğrudur. Pertussis toksini Gi proteinini ADP-ribozilleyerek adenilat siklaz üzerindeki inhibisyonu kaldırır. Sonuçta cAMP artışı gelişir."
