    "explanation": "Doğru cevap A’dır. Herediter hemokromatoziste en sık HFE ilişkili hepcidin düzenleme bozukluğu sonucunda bağırsaktan demir emilimi artar. Plazmada demir yükü arttıkça transferrin satürasyonu yükselir; depo demiri arttığında ferritin de artar. Demir eksikliği anemisinde ise serum demiri ve ferritin azalır, total demir bağlama kapasitesi artar; bu patern hemokromatozisin tersidir. Hemokromatoziste klinik olarak karaciğer hastalığı, diabetes mellitus, hiperpigmentasyon, kardiyomiyopati ve hipogonadizm gibi organ tutulumları gelişebilir. Herediter hemokromatozis genellikle intestinal demir emiliminin artması ve dokularda demir birikimi ile seyreder. Transferrin satürasyonu artışı erken ve önemli bir bulgudur; ferritin de demir yükünü yansıtarak yükselir. TUS açısından ayırıcı nokta: Hemokromatozis = yüksek transferrin satürasyonu + yüksek ferritin; demir eksikliği = düşük ferritin + düşük satürasyon + yüksek TDBK.",
