    "explanation": "Doğru cevap A’dır. Tiroid hormonları özellikle erken yaşamda beyin gelişimi için kritik önemdedir. Konjenital hipotiroidi klinik olarak başlangıçta belirgin bulgu vermeyebilir; bu nedenle tarama programları semptom beklemeden tanı koymayı hedefler. Erken levotiroksin tedavisi nörogelişimsel sekelleri büyük ölçüde önleyebilir. Diğer seçenekler tiroid cerrahisi, sarılık tedavisi, kalp hastalığı taraması veya fenilketonüri yönetimiyle ilgilidir ve konjenital hipotiroidi taramasının temel amacını açıklamaz. Konjenital hipotiroidi yenidoğanda başlangıçta sessiz olabilir; tedavi gecikirse kalıcı nörogelişimsel hasar oluşabilir. Taramanın amacı erken saptama ve levotiroksin tedavisiyle beyin gelişimini korumaktır. TUS açısından ayırıcı nokta: Konjenital hipotiroidi taraması semptom yakalamak için değil, semptom gelişmeden levotiroksin başlayıp nörogelişimi korumak için yapılır.",
