    "explanation": "Doğru cevap A’dır. Komplet mol hidatiformda genetik materyal tipik olarak paternal kökenlidir; en sık 46,XX yapıda olup boş ovumun döllenmesi ve paternal genomun duplikasyonu ile gelişir. Fetal doku veya embriyonik gelişim beklenmez. Trofoblast proliferasyonu yaygındır ve beta-hCG belirgin yüksek olabilir. Parsiyel molde ise genellikle triploidi ve fetal doku parçaları görülebilir. Mol gebeliklerde persistan trofoblastik hastalık riski nedeniyle boşaltım sonrası seri beta-hCG izlemi gerekir. Komplet mol hidatiform çoğunlukla boş ovumun sperm tarafından döllenmesi ve paternal genetik materyalin duplikasyonu sonucu oluşur. Fetal doku yoktur; diffüz trofoblast proliferasyonu ve yüksek beta-hCG düzeyleri beklenebilir. TUS açısından ayırıcı nokta: Komplet mol = paternal genom + fetal doku yok + diffüz trofoblast proliferasyonu + yüksek beta-hCG + takip şart. Parsiyel mol = triploidi + fetal doku olabilir.",
