      "Kolon mukozasında diffüz adenomatöz poliplerin zorunlu olarak malignleşmesi": "Yanlıştır. Diffüz adenomatöz poliplerin malignleşme riski ailesel adenomatöz polipozisle ilişkilidir. Hirschsprung hastalığının temel mekanizması değildir.",
