      "Periferik motor nöronlarda asetilkolin reseptör blokajı": "Yanlıştır. Asetilkolin reseptör blokajı nöromüsküler kavşak ile ilgilidir. Parkinson merkezi bazal ganglion dopamin eksikliğiyle ilişkilidir.",
      "Serebellar Purkinje hücrelerinde primer GABA sentez artışı": "Yanlıştır. Purkinje hücreleri serebellar motor koordinasyonda önemlidir. Parkinsonun temel mekanizması primer serebellar GABA artışı değildir.",
      "Substantia nigra pars compacta dopaminerjik nöron kaybı ve striatal dopamin azalması": "Doğrudur. Substantia nigra pars compacta dopaminerjik nöron kaybı striatal dopamin azalmasına yol açar. Bu, Parkinson motor bulgularının temel mekanizmasıdır.",
