      "Pemfigus vulgariste büller her zaman subepidermaldir ve mukozal tutulum beklenmez": "Yanlıştır. Pemfigus vulgariste büller intraepidermaldir ve mukozal tutulum sık olabilir. Subepidermal bül büllöz pemfigoid lehinedir.",
      "Büllöz pemfigoidde hemidesmozom hedefleri yoktur ve Nikolsky bulgusu daima belirgindir": "Yanlıştır. Büllöz pemfigoidde hemidesmozomal hedefler vardır; BP180 ve BP230 gibi antijenler önemlidir. Nikolsky bulgusu pemfigus vulgariste daha tipik kabul edilir.",
