    "explanation": "Doğru cevap A’dır. Paneth hücreleri ince bağırsak kriptlerinin tabanında bulunan, apikal granülleri belirgin hücrelerdir. Lizozim, defensin ve benzeri antimikrobiyal moleküller salgılayarak bağırsak lümenindeki mikroorganizmalara karşı doğuştan immün savunmaya katkı sağlar. Bu hücreler aynı zamanda intestinal kript kök hücre nişinin düzenlenmesinde de önemlidir. Hidroklorik asit ve intrinsik faktör mide parietal hücreleriyle, safra asidi sentezi hepatositlerle, insülin pankreas beta hücreleriyle ilişkilidir.",
