    "coreKnowledge": "Meckel divertikülü, vitellin/omfalomezenterik kanalın kalıntısıdır. İleumda gerçek divertikül olarak bulunur ve ektopik gastrik veya pankreatik doku içerebilir.",
    "explanation": "Doğru cevap A’dır. Vitellin kanal normalde embriyolojik gelişim sırasında kaybolur; persistan kalıntısı Meckel divertikülüne yol açabilir. Meckel divertikülü bağırsak duvarının tüm katlarını içerdiği için gerçek divertiküldür ve en sık distal ileumda bulunur. Ektopik gastrik mukoza asit salgılayarak ülserasyon ve kanamaya neden olabilir. Ürakoz kalıntıları mesane-umbilikus ilişkili anomalilere, nöral tüp kapanma kusurları spina bifida gibi tablolara, müllerian kanal anomalileri ise kadın genital sistem gelişim bozukluklarına yol açar.",
    "answerAnalysisIntro": "Bu soru embriyolojik kanal kalıntılarını ayırmayı ölçer. Meckel divertikülü için anahtar yapı vitellin kanal, ürakal anomaliler için allantois/ürakoz kalıntısıdır.",
    "optionFeedback": {
      "Ürakozun açık kalması": "Yanlıştır. Ürakozun açık kalması mesane ile umblikus arasında bağlantı veya ürakal kist/sinüs gibi anomalilere neden olur. Meckel divertikülünün kökeni değildir.",
      "Vitellin kanalın proksimal kısmının tamamen kapanmaması": "Doğrudur. Meckel divertikülü vitellin kanalın persistan kalıntısıdır. Distal ileumda gerçek divertikül olarak görülür ve ektopik gastrik mukoza içerebilir.",
      "Nöral tüpün posterior nöropor kapanma kusuru": "Yanlıştır. Posterior nöropor kapanma kusuru spina bifida gibi nöral tüp defektleriyle ilişkilidir. Bağırsak divertikülü mekanizmasını açıklamaz.",
      "Müllerian kanal regresyonunun tamamlanması": "Yanlıştır. Müllerian kanal regresyonu veya persistanlığı genital sistem gelişimiyle ilgilidir. Meckel divertikülü omfalomezenterik kanal kalıntısıdır.",
      "Birinci faringeal yarığın kalıcı kistik genişlemesi": "Yanlıştır. Birinci faringeal yarık anomalileri baş-boyun bölgesi kist ve sinüsleriyle ilişkilidir. İleal divertikül oluşumunu açıklamaz."
    },
