      "Anti-Ro/SSA ve Anti-La/SSB": "Doğrudur. Anti-Ro/SSA ve anti-La/SSB Sjögren sendromu ile klasik olarak ilişkilidir. Göz ve ağız kuruluğu bağlamında bu antikorlar akla gelmelidir.",
      "Anti-GBM ve Anti-PLA2R": "Yanlıştır. Anti-GBM Goodpasture spektrumu ile, anti-PLA2R primer membranöz nefropati ile ilişkilidir. Bu antikorlar sicca sendromunun klasik belirteçleri değildir.",
      "Anti-mitokondriyal antikor ve p-ANCA": "Yanlıştır. Anti-mitokondriyal antikor primer biliyer kolanjit için tipiktir; p-ANCA bazı vaskülitler ve inflamatuvar bağırsak hastalıkları bağlamında görülebilir.",
      "Anti-sentromer ve Anti-HMG-CoA redüktaz": "Yanlıştır. Anti-sentromer sınırlı sistemik sklerozla, anti-HMG-CoA redüktaz statin ilişkili immün aracılı nekrotizan miyopatiyle ilişkilidir. Sjögren için klasik çift değildir."
