    "coreKnowledge": "Tansiyon pnömotoraks yaşamı tehdit eden klinik tanıdır. Hemodinamik bozulma ve ventilasyon problemi oluşturabileceği için görüntüleme beklenmeden acil dekompresyon yapılmalı, ardından kalıcı drenaj için tüp torakostomi uygulanmalıdır.",
    "explanation": "Doğru cevap A’dır. Tansiyon pnömotoraks intratorasik basıncın artması, venöz dönüşün azalması ve obstrüktif şok gelişimiyle sonuçlanabilir. Bu nedenle tanı klinik olarak düşünülür düşünülmez radyolojik doğrulama beklenmemelidir. Acil iğne dekompresyonu basıncı azaltır; ardından tüp torakostomi ile kalıcı hava drenajı sağlanır. Görüntüleme beklemek veya yalnız izlem yapmak yaşamı tehdit eden gecikmeye neden olabilir. Bronkoskopi, antibiyotik veya abdominal BT bu acil fizyolojik problemi çözmez.",
    "answerAnalysisIntro": "Bu soru acil travma yaklaşımında tedavi önceliğini ölçer. Tansiyon pnömotoraks görüntüleme tanısı değil, klinik tanı ve acil müdahale gerektiren durumdur.",
