      "Sadece seri akciğer grafileriyle izlem yapılması": "Yanlıştır. Seri grafiyle izlem stabil küçük pnömotoraks gibi durumlarda düşünülebilir. Tansiyon pnömotoraks acil dekompresyon gerektirir.",
