    "coreKnowledge": "Myastenia gravis, nöromüsküler kavşakta postsinaptik nikotinik asetilkolin reseptörlerine veya ilişkili proteinlere karşı otoantikorlarla gelişir. Kas kullanımıyla artan, dinlenmeyle düzelen fluktuasyon gösteren güçsüzlük tipiktir.",
    "explanation": "Doğru cevap A’dır. Myastenia graviste otoantikorlar postsinaptik asetilkolin reseptörlerini bloke edebilir, kompleman aracılı hasara yol açabilir ve reseptör sayısını azaltabilir. Sonuçta sinaptik iletim güvenlik faktörü düşer; tekrarlayan kullanımda kas güçsüzlüğü belirginleşir. “Presinaptik kalsiyum kanallarına karşı antikor nedeniyle asetilkolin salınımının azalması” seçeneği Lambert-Eaton miyastenik sendromuna daha uygundur; burada presinaptik voltaj kapılı kalsiyum kanalları hedeflenir ve asetilkolin salınımı azalır. “Distrofin yokluğu nedeniyle kas membran bütünlüğünün bozulması” seçeneği distrofinopatileri, E Parkinson hastalığını, “Üst motor nöron kortikospinal trakt dejenerasyonu” seçeneği ise üst motor nöron hastalıklarını düşündürür.",
