      "Ductus biliferus": "Portal triadın temel yapılarından biridir. Ductus biliferus safra akımını hepatositlerden portal alana doğru taşır; kan akımıyla ters yönde ilerler.",
      "Lenfatik damarlar": "Portal alan içinde lenfatik damarlar bulunabilir. Klasik üçlü yapının ana elemanı olmasa da portal alan bileşeni olarak kabul edilebilir."
