    "coreKnowledge": "Sekretin duodenuma gelen asit içeriğe yanıt olarak S hücrelerinden salınır. Pankreas duktal hücrelerinden bikarbonatça zengin sıvı sekresyonunu artırarak duodenal pH’nin nötralize edilmesine katkı sağlar.",
    "explanation": "Doğru cevap A’dır. Sekretin, özellikle duodenuma geçen asidik kimusun uyarısıyla salınır ve pankreas duktus hücrelerinden bikarbonat sekresyonunu artırır. Bikarbonat, gastrik asidi nötralize ederek pankreatik enzimlerin çalışabileceği daha uygun pH ortamını oluşturur. Mide asit sekresyonunu artıran ana hormon gastrindir; safra kesesi kontraksiyonu ve pankreatik enzim sekresyonu ise daha çok kolesistokinin ile ilişkilidir. Bu nedenle sekretin asit yüküne karşı bikarbonat yanıtının hormonu olarak öğrenilmelidir.",
    "answerAnalysisIntro": "Bu soru gastrointestinal hormonları uyarıcı ve hedef etkilerine göre ayırmayı ölçer. Sekretin asit-bikarbonat, CCK yağ/protein-enzim/safra kesesi, gastrin asit sekresyonu ile eşleşir.",
