      "Safra kesesini güçlü biçimde kasarak Oddi sfinkterini kapatır": "Yanlıştır. Safra kesesi kontraksiyonu ve oddi sfinkter relaksasyonu daha çok CCK etkisiyle ilişkilidir. Sekretinin ana etkisi bikarbonat sekresyonudur.",
