      "İleumdan B12-intrinsik faktör kompleksinin emilimini inhibe eder": "Yanlıştır. B12-intrinsik faktör kompleksi terminal ileumdan emilir. Sekretinin temel görevi bu emilimi inhibe etmek değildir.",
